/*
 * A341238  Numbers k such that there do not exist consecutive primes (p,q)
 *          such that (2*k-q,2*k-p) are consecutive primes.
 * https://oeis.org/A341238
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth positive integer k such that for all consecutive
 *            prime pairs (p,q) with p<q, (2*k-q,2*k-p) are not consecutive
 *            primes. The sequence is generated by testing each k
 *            incrementally
 * Range:     u8 n <= 83, u16 n <= 351, u32 n <= 351, u64 n <= 351,
 *            u128 n <= 351, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ---- static state ----------------------------------------------------- */

static seq_t *terms = NULL;          /* stored sequence values          */
static size_t terms_size = 0;        /* number of stored terms          */
static size_t terms_cap  = 0;        /* current allocated capacity      */

static idx_t *prime_list = NULL;     /* list of primes in ascending order */
static size_t prime_count = 0;       /* number of primes stored           */
static idx_t sieve_limit = 0;        /* highest number sieved             */

static uint8_t *is_prime_flag = NULL;/* 1 if number<=sieve_limit is prime */
static idx_t *next_prime_val = NULL; /* for each x: smallest prime > x */

/* ---- local helpers ---------------------------------------------------- */

static void grow_terms(size_t needed)
{
    if (needed <= terms_cap)
        return;
    size_t new_cap = terms_cap ? terms_cap << 1 : 16;
    while (new_cap < needed)
        new_cap <<= 1;
    seq_t *newp = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
    if (!newp)
        exit(EXIT_FAILURE);
    terms = newp;
    terms_cap = new_cap;
}

static void init_sieve(idx_t limit)
{
    /* free previous data */
    free(is_prime_flag);
    free(next_prime_val);
    free(prime_list);

    /* allocate arrays */
    is_prime_flag = (uint8_t *)malloc((size_t)(limit + 1));
    if (!is_prime_flag)
        exit(EXIT_FAILURE);
    for (idx_t i = 0; i <= limit; ++i)
        is_prime_flag[i] = 1;
    if (limit >= 0) is_prime_flag[0] = 0;
    if (limit >= 1) is_prime_flag[1] = 0;

    /* simple sieve of Eratosthenes */
    for (idx_t i = 2; i * i <= limit; ++i) {
        if (is_prime_flag[i]) {
            for (idx_t j = i * i; j <= limit; j += i)
                is_prime_flag[j] = 0;
        }
    }

    /* collect primes */
    size_t cap = 16;
    prime_count = 0;
    prime_list = (idx_t *)malloc(cap * sizeof(idx_t));
    if (!prime_list)
        exit(EXIT_FAILURE);

    for (idx_t i = 2; i <= limit; ++i) {
        if (is_prime_flag[i]) {
            if (prime_count == cap) {
                cap <<= 1;
                idx_t *tmp = (idx_t *)realloc(prime_list, cap * sizeof(idx_t));
                if (!tmp)
                    exit(EXIT_FAILURE);
                prime_list = tmp;
            }
            prime_list[prime_count++] = i;
        }
    }

    /* next_prime array: next_prime_val[x] = smallest prime > x, or 0 */
    next_prime_val = (idx_t *)malloc((size_t)(limit + 1) * sizeof(idx_t));
    if (!next_prime_val)
        exit(EXIT_FAILURE);

    next_prime_val[limit] = 0;
    for (idx_t x = limit; x > 0; --x) {
        if (is_prime_flag[x])
            next_prime_val[x - 1] = x;
        else
            next_prime_val[x - 1] = next_prime_val[x];
    }
    next_prime_val[0] = next_prime_val[1]; /* any number > 0 already filled */

    sieve_limit = limit;
}

static void ensure_sieve(idx_t needed)
{
    if (needed <= sieve_limit)
        return;
    /* grow by doubling */
    idx_t new_limit = sieve_limit ? sieve_limit << 1 : needed;
    while (new_limit < needed) {
        new_limit <<= 1;
        if (new_limit < needed) /* avoid overflow */
            new_limit = needed;
    }
    init_sieve(new_limit);
}

static bool k_is_excluded(idx_t k)
{
    idx_t high = k * 2;
    ensure_sieve(high);

    /* iterate over consecutive prime pairs p<=q with q <= high */
    for (size_t i = 0; i + 1 < prime_count; ++i) {
        idx_t p = prime_list[i];
        idx_t q = prime_list[i + 1];
        if (q > high) /* further q will be even larger */
            break;

        idx_t x = high - q; /* 2*k - q */
        if (x < 2)
            break;          /* all further x will be even smaller */

        idx_t y = high - p; /* 2*k - p, automatically > x */

        if (is_prime_flag[x] && next_prime_val[x] == y)
            return true;   /* excluded */
    }
    return false;
}

/* ---- exported function ----------------------------------------------- */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0; /* undefined for 0, protect */

    /* lazy initialization of the primes table */
    if (!sieve_limit)
        init_sieve(16); /* very small initial sieve */

    /* generate terms until we have enough */
    static idx_t last_checked = 0;
    while (terms_size < (size_t)n) {
        idx_t k = last_checked + 1;
        if (!k_is_excluded(k)) {
            grow_terms(terms_size + 1);
            terms[terms_size++] = (seq_t)k;
        }
        last_checked = k;
    }
    return terms[(size_t)n - 1];
}
